<?php require_once 'config.php';$st=$pdo->prepare("SELECT * FROM products WHERE id=?");$st->execute([(int)($_GET['id']??0)]);$p=$st->fetch();if(!$p){header('Location: shop.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$_SESSION['cart'][$p['id']]=($_SESSION['cart'][$p['id']]??0)+max(1,(int)$_POST['qty']);$_SESSION['flash']='Added to your bag!';go('cart.php');}$title=$p['name'];include 'header.php';?><div class="row g-5"><div class="col-md-6"><img class="w-100 rounded-4" style="height:450px;object-fit:cover" src="<?= h($p['image_url']) ?>"></div><div class="col-md-6"><h1><?= h($p['name']) ?></h1><p class="price fs-4"><?= money($p['price']) ?></p><p><?= h($p['description']) ?></p><form method="post"><input class="form-control mb-3" style="max-width:100px" type="number" min="1" max="10" name="qty" value="1"><button class="btn btn-rose">ADD TO BAG</button></form></div></div><?php include 'footer.php'; ?>
